   <div class="panel reference-events"><div class="ref-title"><h3>Последние события</h3><button class="btn" data-go="audit">Все</button></div>${recent.map(e=>`<div class="reference-event"><time>${date(e.created).slice(-5)}</time><span class="event-dot"></span><b>${esc(e.nickname)}</b><p>${esc(e.event)}</p></div>`).join('')||'<div class="empty">Событий пока нет.</div>'}</div>
