let examIndex=0, examStartedAt=0, examTimer=null;
function startExamTimer(){clearInterval(examTimer);const tick=()=>{const left=Math.max(0,1800-(Math.floor(Date.now()/1000)-examStartedAt));const m=String(Math.floor(left/60)).padStart(2,'0'),sec=String(left%60).padStart(2,'0');const el=$('#examTimer');if(el)el.textContent=`${m}:${sec}`;if(left<=0){clearInterval(examTimer);alert('30 минут истекли. Аттестация закрыта.');location.reload()}};tick();examTimer=setInterval(tick,1000)}
