function smoothHTML(html){const app=$('#app');app.classList.remove('page-enter');void app.offsetWidth;app.innerHTML=html;app.classList.add('page-enter');}
async function renderOperational(){
 if(!isStaff()) return renderHome(); const d=await api('/api/operational');
 smoothHTML(shell('ОПЕРАТИВНАЯ <em>ОБСТАНОВКА</em>','КОМАНДНЫЙ ЦЕНТР','Текущее состояние состава и задачи руководства.',`
 <div class="ops-grid"><div class="ops-card"><span>🟢</span><small>СОСТАВ</small><b>${d.staff}</b><em>в системе</em></div><div class="ops-card"><span>🟢</span><small>ОНЛАЙН</small><b>${d.online}</b><em>за последние 15 минут</em></div><div class="ops-card"><span>🟡</span><small>НА ПРОВЕРКЕ</small><b>${d.checking}</b><em>аттестаций</em></div><div class="ops-card"><span>🔴</span><small>ПРОБЛЕМЫ</small><b>${d.problems}</b><em>требуют внимания</em></div></div>
 <div class="split-grid"><section class="panel pad"><div class="ref-title"><h3>Что требует внимания</h3><span class="badge ${d.problems?'warn':'ok'}">${d.problems?'Есть задачи':'Всё спокойно'}</span></div><div class="attention-list"><button data-go="requests">📋 Заявки на должность <b>${d.pending_roles}</b></button><button data-go="requests">🛡 Заявки на аттестацию <b>${d.pending_exam}</b></button><button data-go="reviews">📝 Работы на проверке <b>${d.checking}</b></button><button data-go="security">🔒 Заблокированные <b>${d.blocked}</b></button></div></section><section class="panel pad"><div class="ref-title"><h3>Последние события</h3><button class="btn" data-go="audit">Открыть журнал</button></div><div class="history-mini">${d.events.map(e=>`<div><time>${date(e.created)}</time><span><b>${esc(e.nickname)}</b> — ${esc(e.event)}</span></div>`).join('')||'<div class="empty">Событий нет.</div>'}</div></section></div>`));$$('[data-go]').forEach(b=>b.onclick=()=>navPage(b.dataset.go));
}
