async function renderTraining(){
 if(!user)return openAuth();
 smoothHTML(shell('ТРЕНИРОВОЧНЫЙ <em>РЕЖИМ</em>','ОБУЧЕНИЕ','Тренировка не влияет на официальный результат аттестации.',`<div id="trainingRoot"><div class="panel pad training-intro"><div class="training-icon">🧠</div><h3>Подготовка к аттестации</h3><p>10 случайных письменных вопросов. После завершения система покажет заполненность и слабую тему. Официальная проверка выполняется инструктором.</p><button class="red-btn" id="trainingStart">Начать тренировку</button></div></div>`));$('#trainingStart').onclick=startTraining;
}
async function startTraining(){try{const d=await api('/api/training/start',{method:'POST'});let i=0,ans={};const root=$('#trainingRoot');const paint=()=>{const q=d.questions[i];root.innerHTML=`<div class="panel pad training-card"><div class="exam-one-top"><span class="section-tag">ТРЕНИРОВКА · ${i+1}/10</span><span class="exam-random">БЕЗ ВЛИЯНИЯ НА АТТЕСТАЦИЮ</span></div><h2>${esc(q.body)}</h2><textarea id="trainAnswer" class="answer exam-answer" placeholder="Ваш письменный ответ…">${esc(ans[q.id]||'')}</textarea><div class="exam-nav"><button class="btn" id="trainPrev" ${i===0?'disabled':''}>← Назад</button><span class="exam-counter">${Object.values(ans).filter(Boolean).length} / 10</span>${i===d.questions.length-1?'<button class="red-btn" id="trainFinish">Завершить</button>':'<button class="red-btn" id="trainNext">Следующий →</button>'}</div></div>`;$('#trainAnswer').oninput=e=>ans[q.id]=e.target.value;$('#trainPrev')?.addEventListener('click',()=>{ans[q.id]=$('#trainAnswer').value;i--;paint()});$('#trainNext')?.addEventListener('click',()=>{ans[q.id]=$('#trainAnswer').value;i++;paint()});$('#trainFinish')?.addEventListener('click',async()=>{ans[q.id]=$('#trainAnswer').value;const r=await api('/api/training/submit',{method:'POST',body:JSON.stringify({attempt_id:d.id,answers:ans})});root.innerHTML=`<div class="panel pad training-result"><div class="scorebox">${r.score} / 10</div><h3>Тренировка завершена</h3><p>Заполнено письменных ответов: ${r.score} из 10.</p><div class="weak-topic">Слабая тема для повторения: <b>${esc(r.weak_theme)}</b></div><p class="muted">${esc(r.note)}</p><button class="red-btn" id="againTraining">Пройти ещё раз</button></div>`;$('#againTraining').onclick=startTraining});};paint()}catch(e){alert(e.message)}}
