function syncV14Nav(){ $$('.nav-item.staff-only').forEach(x=>x.classList.toggle('hidden',!isStaff())); $$('.nav-item.owner-only').forEach(x=>x.classList.toggle('hidden',!isOwner())); }
const _loadMeV13=loadMe;
loadMe=async function(){const r=await _loadMeV13();syncV14Nav();return r};
